package local.hy320.helperstarter;
import android.content.Context;import android.os.*;
final class ProbeState {
 static volatile String status="Ready";static volatile boolean visible;static volatile LocalAdb active;private static boolean running;
 static synchronized void pair(Context context,Bundle input)throws Exception{if(running||!visible)throw new IllegalStateException("Open the local client page first");if(Build.VERSION.SDK_INT!=34||!"Projector_20260713.153921".equals(Build.ID))throw new SecurityException("Unexpected projector");final int pairPort=input.getInt("pair_port"),connectPort=input.getInt("connect_port");final String code=input.getString("code");if(pairPort<1||pairPort>65535||connectPort<1||connectPort>65535||code==null||!code.matches("[0-9]{6}"))throw new IllegalArgumentException("Pairing inputs unavailable");running=true;status="Pairing local identity...";
 new Thread(()->{try{PairingContext.selfTest();ClientIdentity identity=new ClientIdentity();try(LocalAdb pair=new LocalAdb()){active=pair;pair.pair(context,identity,pairPort,code);}if(!visible)throw new IllegalStateException("Page closed");status="Stopped: Pairing complete; authorised service enrolment required";}
 catch(Throwable failure){Throwable cause=failure;while(cause.getCause()!=null)cause=cause.getCause();status="Stopped: "+cause.getClass().getSimpleName()+": "+String.valueOf(cause.getMessage());android.util.Log.w("CYTVLocalClient",status);}
 finally{synchronized(ProbeState.class){active=null;running=false;}}},"local-client-pairing").start();}
 static synchronized void verify(Context context,Bundle input)throws Exception{
 if(running||!visible)throw new IllegalStateException("Open the local client page first");String pin=input.getString("connect_pin");int port=input.getInt("connect_port");android.content.SharedPreferences prefs=context.getSharedPreferences("identity",0);if(!prefs.getBoolean("paired",false))throw new IllegalStateException("Pair the local identity first");if(pin==null||!pin.matches("[A-Za-z0-9+/]{43}="))throw new IllegalArgumentException("Trusted local service pin required");String existing=prefs.getString("connect_server_pin",null);if(existing!=null&&!existing.equals(pin)&&!input.getBoolean("replace_enrolment",false))throw new SecurityException("Previously enrolled service identity changed");if(!prefs.edit().putString("connect_server_pin",pin).putInt("pin_boot",android.provider.Settings.Global.getInt(context.getContentResolver(),"boot_count",-1)).commit())throw new IllegalStateException("Pin could not be saved");running=true;status="Checking authenticated local shell...";new Thread(()->{try(LocalAdb client=new LocalAdb()){active=client;status=client.identityCheck(context,new ClientIdentity(),port)+"\nLocal authentication verified";}catch(Throwable e){Throwable cause=e;while(cause.getCause()!=null)cause=cause.getCause();status="Stopped: "+cause.getClass().getSimpleName()+": "+cause.getMessage();}finally{synchronized(ProbeState.class){active=null;running=false;}}},"local-client-check").start();
 }
 static synchronized void cancel(){if(active!=null)active.close();}
}
